"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface EmptyStateProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  icon?: React.ReactNode;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Knoppen onderaan. */
  action?: React.ReactNode;
  size?: "sm" | "md";
}

/** EmptyState — lege lijst, geen resultaten, nog niets ingesteld. */
export const EmptyState = React.forwardRef<HTMLDivElement, EmptyStateProps>(function EmptyState(
  { icon, title, description, action, size = "md", className, children, ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("pxui-empty", `pxui-empty-${size}`, className)} {...rest}>
      {icon && <div className="pxui-empty-icon">{icon}</div>}
      <div className="pxui-empty-title">{title}</div>
      {description && <p className="pxui-empty-description">{description}</p>}
      {children}
      {action && <div className="pxui-empty-action">{action}</div>}
    </div>
  );
});

/* ============================ EmptyState ============================ */
.pxui-empty {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  gap: 8px; padding: 52px 24px;
}
.pxui-empty-sm { padding: 30px 18px; }
.pxui-empty-icon {
  display: grid; place-items: center; width: 56px; height: 56px;
  border-radius: var(--r-lg); background: var(--surface-2);
  border: 1px solid var(--border); color: var(--text-3); margin-bottom: 6px;
}
.pxui-empty-icon svg { width: 24px; height: 24px; }
.pxui-empty-sm .pxui-empty-icon { width: 44px; height: 44px; }
.pxui-empty-title { font-size: var(--fs-lg); font-weight: 650; letter-spacing: -0.02em; color: var(--text); }
.pxui-empty-sm .pxui-empty-title { font-size: 14.5px; }
.pxui-empty-description { font-size: 13.5px; color: var(--text-3); max-width: 380px; line-height: 1.55; }
.pxui-empty-action { display: flex; gap: 10px; margin-top: 10px; flex-wrap: wrap; justify-content: center; }
